import math

def nearest(p, line):
    best=None
    bd=1e9
    for a,b in zip(line,line[1:]):
        dx=b[0]-a[0]; dy=b[1]-a[1]
        q=max(0,min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy+1e-9)))
        x=a[0]+q*dx; y=a[1]+q*dy
        d=(x-p[0])**2+(y-p[1])**2
        if d<bd: bd=d; best=(x,y)
    return best,bd

def control(obs):
    lm=obs['local_map']; left=lm['left_rail']; right=lm['right_rail']
    mids=[]
    for rail,other in ((left,right),(right,left)):
        for p in rail:
            q,d=nearest(p,other)
            if q is not None and 1.0<d<30:
                x=(p[0]+q[0])/2; y=(p[1]+q[1])/2
                if x>0: mids.append((x,y))
    look=1.5
    if mids:
        x,y=min(mids,key=lambda p:abs(math.hypot(*p)-look)+max(0,-p[0])*5)
        curvature=2*y/(x*x+y*y+0.9*x+0.01)
    else:
        curvature=0
    desired=max(-25,min(25,math.degrees(math.atan(0.85*curvature))))
    h=obs['hitch_deg']; hr=math.radians(h)
    feed=math.degrees(math.atan(1.25*math.sin(hr)/(0.85+0.3*math.cos(hr))))
    steer=max(-45,min(45,feed+2.5*(h-desired)))
    speed=-max(0.28,0.65-0.012*abs(desired)-0.007*abs(h-desired))
    if abs(h)>38:
        wake('Hitch angle needs attention')
        return steer,0
    return steer,speed

